std::array<unsigned char, 16> digest = md5(msg);
unsigned long long sum = 0;
unsigned long long base = 1;
for (std::size_t i = 0; i < digest.size(); ++i) {
    sum += static_cast<unsigned long long>(digest[i]) * base;
    base *= 131;
}
float result = static_cast<float>(sum % 1000000) / 1000000.0f;
return result;

